sys_ui_action.script:
current.setValue('state', '3');
current.update();

var grMedia = new GlideRecord("x_1807247_netflix_media");
grMedia.addEncodedQuery("title=" + current.getValue('title') +
"^type=" + current.getValue('type') +
"^release_year=" + current.getValue('release_year') +
"^sys_id!=" + current.getValue('sys_id'));
grMedia.query();

while (grMedia.next()) {
	grMedia.setValue('state', '7');
	grMedia.setValue("genre", "");
	grMedia.setValue("synopsis", "");
	grMedia.setValue("category", "");
	grMedia.setValue("writers", "");
	grMedia.setValue("awards", "");
	grMedia.setValue("language", "");
	grMedia.setValue("country", "");
	grMedia.setValue("imdb_rating", "");
	grMedia.setValue("metascore", "");
	grMedia.setValue("website", "");
	grMedia.setValue("production", "");
	grMedia.setValue("poster", "");
	grMedia.setValue("average_rating", "");

    var grMediaActor = new GlideRecord("x_1807247_netflix_m2m_actors_medias");
    grMediaActor.addEncodedQuery("x_1807247_netflix_media=" + grMedia.getValue("sys_id"));
    grMediaActor.query();
    grMediaActor.deleteMultiple();

    var grMediaDirector = new GlideRecord("x_1807247_netflix_m2m_directors_medias");
    grMediaDirector.addEncodedQuery("x_1807247_netflix_media=" + grMedia.getValue("sys_id"));
    grMediaDirector.query();
    grMediaDirector.deleteMultiple();

    grMedia.update();
}

action.setRedirectURL(current);
